mapper.select:
SELECT  FROM payment_order o WHERE 1=1
AND o.parent_user_id=#{owner}
AND EXISTS(SELECT 1 FROM payment p WHERE p.order_id=o.id AND p.status=#{status})
AND o.created_at >= (#{from}::date::timestamp AT TIME ZONE 'Asia/Seoul')
AND o.created_at < ((#{to}::date+1)::timestamp AT TIME ZONE 'Asia/Seoul')
ORDER BY o.created_at DESC,o.id LIMIT #{size} OFFSET #{offset}
